    "compose": "# RabbitMQ with the management plugin. AMQP stays internal; the management UI is\n# bound to localhost for debugging.\nname: arvion-rabbitmq\n\nservices:\n  rabbitmq:\n    image: rabbitmq:3.13.7-management-alpine\n    restart: unless-stopped\n    environment:\n      RABBITMQ_DEFAULT_USER: ${RABBITMQ_USER:-app}\n      RABBITMQ_DEFAULT_PASS: ${RABBITMQ_PASSWORD:-change-me}\n      RABBITMQ_DEFAULT_VHOST: ${RABBITMQ_VHOST:-app}\n    ports:\n      - \"127.0.0.1:${RABBITMQ_MGMT_PORT:-15672}:15672\"\n    volumes:\n      - rabbitmq-data:/var/lib/rabbitmq\n    healthcheck:\n      test: [\"CMD\", \"rabbitmq-diagnostics\", \"-q\", \"ping\"]\n      interval: 15s\n      timeout: 10s\n      retries: 5\n      start_period: 30s\n    mem_limit: 384m\n    cpus: 1.0\n    networks:\n      - messaging\n\nvolumes:\n  rabbitmq-data:\n\nnetworks:\n  messaging:\n    driver: bridge\n",
